from collections import Counter, deque
def comps(g,bg):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                st=[(r,c)]; comp=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen or g[a][b]==bg: continue
                    seen.add((a,b)); comp.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            q=(a+dr,b+dc)
                            if 0<=q[0]<H and 0<=q[1]<W and q not in seen and g[q[0]][q[1]]!=bg: st.append(q)
                out.append(comp)
    return out
def f(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    cs=comps(g,bg)
    # shape = largest component
    cs.sort(key=len,reverse=True)
    patch=max(cs,key=len)
    out=[row[:] for row in g]
    tr=min(p[0] for p in patch); tc=min(p[1] for p in patch)
    wr=max(p[0]-tr for p in patch); wc=max(p[1]-tc for p in patch)
    hrc=int((wr+1)/2); hc=int(wc/2)      # bbox center cell indices
    cr=tr+hrc; cc=tc+hc
    for comp in cs:
        if comp==patch: continue
        for cell in comp:
            rr=cell[0]; cc2=cell[1]
            for a,b in patch:
                x=rr-(cc-b); y=cc2-(hc-a)
                if 0<=x<H and 0<=y<W:
                    out[x][y]=g[b][a]
    return out
